  "cau-uoc": [
    { q: "I wish I ___ more time to spend with my family these days.", o: ["had", "have", "will have", "having"], a: 0, hint: "Ước về điều KHÔNG có thật ở HIỆN TẠI: 'wish + S + quá khứ đơn'.", e: "Wish về hiện tại (điều không có thật bây giờ) → quá khứ đơn 'had'." },
    { q: "I wish I ___ harder for the exam last year — I really regret not doing so.", o: ["had studied", "studied", "would study", "have studied"], a: 0, hint: "Tiếc nuối về điều đã KHÔNG xảy ra trong QUÁ KHỨ: 'wish + S + quá khứ hoàn thành'.", e: "Wish tiếc nuối về quá khứ → quá khứ hoàn thành 'had studied'." },
    { q: "I wish you ___ interrupting me every time I try to explain something!", o: ["would stop", "stopped", "stop", "will stop"], a: 0, hint: "Ước một người KHÁC (hoặc sự vật) thay đổi HÀNH VI gây khó chịu, mang sắc thái phàn nàn: 'wish + S + would + V'.", e: "'wish + S (khác) + would + V' diễn tả mong muốn ai đó thay đổi hành vi, thường mang sắc thái phàn nàn." },
    { q: "It's time we ___ heading home — it's getting quite late.", o: ["started", "start", "will start", "starting"], a: 0, hint: "Cấu trúc giả định 'It's (high) time' (đã đến lúc phải làm gì) + chủ ngữ + QUÁ KHỨ ĐƠN.", e: "'It's time + S + quá khứ đơn' — cấu trúc giả định, không phải thì quá khứ thật." },
    { q: "If only I ___ what I know now back when I made that decision.", o: ["had known", "knew", "know", "would know"], a: 0, hint: "'If only' tiếc nuối về điều đã KHÔNG xảy ra trong quá khứ — dùng QUÁ KHỨ HOÀN THÀNH, giống 'wish' cho quá khứ.", e: "'If only' + quá khứ hoàn thành khi tiếc nuối về quá khứ, tương đương 'I wish + quá khứ hoàn thành'." },
    { q: "She talks about her ex-boyfriend as if he ___ still part of her life.", o: ["were", "was", "is", "had been"], a: 0, hint: "'as if/as though' diễn tả điều GIẢ ĐỊNH, KHÔNG có thật ở hiện tại → dùng 'were' (thể giả định chuẩn mực) cho mọi ngôi.", e: "'as if + were' (giả định trái hiện tại) — 'were' dùng cho mọi ngôi trong văn phong chuẩn mực." },
    { q: "He behaves as if he ___ the boss, even though he's just a regular employee.", o: ["were", "is", "was", "will be"], a: 0, hint: "'as if' diễn tả điều GIẢ ĐỊNH trái với thực tế hiện tại (anh ta không phải sếp) → 'were' cho mọi ngôi.", e: "Thực tế trái ngược với điều được diễn tả (anh ta không phải sếp) → thể giả định 'were'." },
    { q: "It's essential that every employee ___ the new safety regulations immediately.", o: ["follow", "follows", "followed", "will follow"], a: 0, hint: "Sau các cụm nhấn mạnh sự CẦN THIẾT ('It's essential/vital/important that') dùng THỂ GIẢ ĐỊNH: V nguyên mẫu, không chia theo ngôi.", e: "'It's essential that + S + V nguyên mẫu' (thể giả định) — 'follow', không phải 'follows'." },
    { q: "I'd rather you ___ smoke in the house — it really bothers me.", o: ["didn't", "don't", "won't", "haven't"], a: 0, hint: "'would rather + S (khác) + quá khứ đơn' diễn tả mong muốn ở HIỆN TẠI về hành vi của người khác — dạng phủ định dùng quá khứ đơn.", e: "'would rather + S khác + quá khứ đơn' (kể cả ở dạng phủ định) — 'didn't smoke' diễn tả mong muốn hiện tại." },
    { q: "The committee demanded that the report ___ revised before the next meeting.", o: ["be", "is", "was", "would be"], a: 0, hint: "Sau động từ 'demand that' dùng THỂ GIẢ ĐỊNH: V nguyên mẫu (kể cả ở dạng bị động 'be + V3').", e: "'demand that + S + V nguyên mẫu' (thể giả định), kể cả ở dạng bị động: 'be revised'." },
    { q: "If only she ___ to me before making such a rash decision!", o: ["had listened", "listened", "would listen", "listens"], a: 0, hint: "'If only' + tiếc nuối về một hành động đã KHÔNG xảy ra trong quá khứ → quá khứ hoàn thành.", e: "'If only' tiếc nuối quá khứ → quá khứ hoàn thành 'had listened'." },
    { q: "I wish it ___ raining so we could go for a walk in the park.", o: ["would stop", "stopped", "stops", "will stop"], a: 0, hint: "Ước một hiện tượng/tình huống bên ngoài thay đổi (mưa ngừng), mang tính mong đợi: 'wish + would + V'.", e: "'wish + would + V' diễn tả mong muốn một sự việc/tình huống thay đổi, thường không nằm trong tầm kiểm soát của người nói." },
  ],

